  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  assert.strictEqual(data.length, count);
  if (title) {
    assert.strictEqual(data[data.length - 1].title, title);
  }
});

Given('the first todo is completed', function () {
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  if (data.length > 0) data[0].completed = true;
  this.localStorage.setItem('todos-vanillajs', JSON.stringify(data));
  // Also update DOM
  const firstLi = this.document.querySelector('.todo-list li:first-child');
  if (firstLi) {
    firstLi.classList.add('completed');
    firstLi.querySelector('.toggle').checked = true;
  }
});

When('I inspect localStorage', function () {
  // Just a pass-through; the Then step reads it
});

Then('the stored data conforms to the {string} schema in {string}', function (schemaName, schemaPath) {
  const schemaFile = path.join(ROOT, schemaPath);
  const schema = JSON.parse(fs.readFileSync(schemaFile, 'utf8'));
  const data = JSON.parse(this.localStorage.getItem('todos-vanillajs') || '[]');
  const ajv = new Ajv();
  const validate = ajv.compile(schema.schema);
  const valid = validate(data);
  assert.ok(valid, JSON.stringify(validate.errors, null, 2));
});

// ── Helpers ─────────────────────────────────────────────────────────────────

function addTodoItem(document, window, title, completed) {
  const li = document.createElement('li');
  if (completed) li.classList.add('completed');
  li.innerHTML =
    '<div class="view">' +
    '<input class="toggle" type="checkbox"' + (completed ? ' checked' : '') + '>' +
    '<label>' + escapeHtml(document, title) + '</label>' +
    '<button class="destroy"></button>' +
    '</div>' +
    '<input class="edit" value="' + escapeHtml(document, title) + '">';
  document.querySelector('.todo-list').appendChild(li);
}

function updateTodoCount(document) {
  const active = document.querySelectorAll('.todo-list li:not(.completed)').length;
  const countEl = document.querySelector('.todo-count');
  if (countEl) {
    const strong = countEl.querySelector('strong') || document.createElement('strong');
    strong.textContent = active;
    if (!countEl.querySelector('strong')) countEl.prepend(strong);
    countEl.childNodes.forEach(n => {
      if (n.nodeType === 3) n.textContent = ' item' + (active === 1 ? ' left' : 's left');
    });
  }
}

function escapeHtml(doc, str) {
  const div = doc.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

