// ── Helpers ─────────────────────────────────────────────────────────────────

function addTodoItem(document, window, title, completed) {
  const li = document.createElement('li');
  if (completed) li.classList.add('completed');
  li.innerHTML =
    '<div class="view">' +
    '<input class="toggle" type="checkbox"' + (completed ? ' checked' : '') + '>' +
    '<label>' + escapeHtml(document, title) + '</label>' +
    '<button class="destroy"></button>' +
    '</div>' +
    '<input class="edit" value="' + escapeHtml(document, title) + '">';
  document.querySelector('.todo-list').appendChild(li);
}

function updateTodoCount(document) {
  const active = document.querySelectorAll('.todo-list li:not(.completed)').length;
  const countEl = document.querySelector('.todo-count');
  if (countEl) {
    const strong = countEl.querySelector('strong') || document.createElement('strong');
    strong.textContent = active;
    if (!countEl.querySelector('strong')) countEl.prepend(strong);
    countEl.childNodes.forEach(n => {
      if (n.nodeType === 3) n.textContent = ' item' + (active === 1 ? ' left' : 's left');
    });
  }
}

function escapeHtml(doc, str) {
  const div = doc.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

