// ── Helper: add todos through the app's new-todo input ─────────────────

function addTodosViaApp(ctx, titles) {
  const input = ctx.document.querySelector('.new-todo');
  for (const title of titles) {
    input.value = title;
    const event = new ctx.window.KeyboardEvent('keydown', {
      key: 'Enter',
      keyCode: 13,
      which: 13,
      bubbles: true,
    });
    input.dispatchEvent(event);
  }
}

// ── Display behavior ────────────────────────────────────────────────────────

Given('the todo list is empty', function () {
  // Clear all todos from DOM and localStorage
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  this.document.querySelector('.main').style.display = 'none';
  this.document.querySelector('.footer').style.display = 'none';
  const countEl = this.document.querySelector('.todo-count');
  if (countEl) countEl.innerHTML = '<strong>0</strong> items left';
});

Given('the todo list has {int} item{ending}', function (count, _) {
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, Array.from({ length: count }, (_, i) => 'Item ' + (i + 1)));
});

Given('the todo list has {int} completed item{ending}', function (count, _) {
  // Create via app, then toggle
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, Array.from({ length: count }, (_, i) => 'Item ' + (i + 1)));
  const items = this.document.querySelectorAll('.todo-list li');
  for (const li of items) li.querySelector('.toggle').click();
});

Given('the todo list has {int} item{ending} with title {string}', function (count, _, title) {
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, [title]);
});

Given('the todo list has {int} completed item{ending} with title {string}', function (count, _, title) {
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, [title]);
  const li = this.document.querySelector('.todo-list li:first-child');
  if (li) li.querySelector('.toggle').click();
});

Given('the todo list has items {string}, {string}', function (t1, t2) {
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, [t1, t2]);
});

Given('the todo list has items {string}, {string}, {string}', function (t1, t2, t3) {
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, [t1, t2, t3]);
});

Given('the todo list has {int} items with titles {string}, {string}', function (count, t1, t2) {
  this.document.querySelector('.todo-list').innerHTML = '';
  this.localStorage.removeItem('todos-vanillajs');
  addTodosViaApp(this, [t1, t2]);
});

